// ── Animation plates ────────────────────────────────────────────────────────
// Every screen below is a real capture of the app, taken by
// content/screenshot-harness (`node capture.js anim`) and packed by
// scripts/build-anim.mjs. Each plate is a whole 16:9 display, which is exactly
// what the bezel wants, and the moving pieces the animations need on top,
// a travelling window, a cursor, a right-click menu, are separate plates so
// they can be animated over it. Nothing here draws a fake app.
const plate = (name) => `/anim/${name}.webp`;
const PLATE_DIMENSIONS = {
  'hero-desktop': [1400, 788],
  'hero-mirror': [620, 1342],
  'menu-context': [410, 716],
  'window-float': [700, 485],
  'window-float-2': [420, 544],
};
// Bing reports alt="" as missing, so every plate gets a short description.
const plateAlt = (name) => `XeOS on an external display: ${name.replace(/-\d+$/, '').replace(/-/g, ' ')}`;
const plateDimensions = (name) => PLATE_DIMENSIONS[name] || [1040, 585];
// Every width scripts/build-anim.mjs writes (RESPONSIVE_WIDTHS there, plus the
// full-size plate last), so the browser picks the closest one.
const PLATE_SRCSET_WIDTHS = {
  'hero-desktop': [480, 720, 1040],
  'hero-mirror': [140, 260, 400],
  'menu-context': [160],
  'window-float': [320],
  'window-float-2': [],
};
const plateSrcSet = (name) => {
  const widths = PLATE_SRCSET_WIDTHS[name] || [360, 520, 720];
  const large = plateDimensions(name)[0];
  return [...widths.map((w) => `/anim/${name}-${w}.webp ${w}w`), `${plate(name)} ${large}w`].join(', ');
};

const Plate = ({ name, visible = true, eager = false, fit = 'cover', style = {}, className }) => {
  const [width, height] = plateDimensions(name);
  return (
    <img
      srcSet={plateSrcSet(name)}
      sizes="(min-width: 1024px) 480px, (min-width: 768px) 44vw, calc(100vw - 48px)"
      src={plate(name)}
      alt={plateAlt(name)}
      width={width}
      height={height}
      className={className}
      loading={eager ? 'eager' : 'lazy'}
      fetchPriority={eager ? 'high' : 'auto'}
      decoding="async"
      style={{
        position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: fit,
        opacity: visible ? 1 : 0, transition: 'opacity 0.55s ease', ...style,
      }}
    />
  );
};

/** Crossfade between plates; `index` says which one is on top. */
const PlateStack = ({ frames, index, eager = false }) => (
  <div style={{ position: 'absolute', inset: 0, background: '#0b1220', overflow: 'hidden' }}>
    {frames.map((name, i) => <Plate key={name} name={name} visible={i === index} eager={eager && i === 0} />)}
  </div>
);

