// ── Feature demo card – title on top, mockup + text side by side (alternating) ─
// A card either flips between two states (the before/after video one) or steps
// through a sequence of real screens; `steps` labels them and doubles as the
// control, so the reader can stop the loop on whichever screen they want.
const FeatureDemoCard = ({
  icon: Icon, iconBg, title, description, points,
  Content, steps = null, hasBeforeAfter = false, toggleBeforeLabel, toggleAfterLabel, reverse = false, interval = 4600, id,
}) => {
  const [isBefore, setIsBefore] = useState(true);
  const [index, setIndex] = useState(0);
  const timerRef = useRef(null);

  const restart = useCallback(() => {
    clearInterval(timerRef.current);
    if (hasBeforeAfter) {
      timerRef.current = setInterval(() => setIsBefore((v) => !v), interval);
    } else if (steps && steps.length > 1) {
      timerRef.current = setInterval(() => setIndex((i) => (i + 1) % steps.length), interval);
    }
  }, [hasBeforeAfter, steps, interval]);

  useEffect(() => {
    restart();
    return () => clearInterval(timerRef.current);
  }, [restart]);

  const titleRow = (
    <div className="demo-card-title flex items-center gap-3">
      <div className={`demo-card-icon w-9 h-9 ${iconBg} rounded-xl flex items-center justify-center flex-shrink-0`}>
        <Icon className="w-5 h-5 text-white" />
      </div>
      <h3 className="text-lg sm:text-xl font-bold text-white">{title}</h3>
    </div>
  );

  const mockupEl = (
    <div className={`demo-card-visual ${reverse ? 'md:order-2' : ''}`}>
      <IMacMockup imgClassName="w-full">
        <Content isBefore={isBefore} index={index} />
      </IMacMockup>
      {(hasBeforeAfter || (steps && steps.length > 1)) && (
        <div className="demo-stepper flex flex-wrap justify-center gap-2 mt-2">
          {hasBeforeAfter ? (
            <>
              <button onClick={() => { setIsBefore(true); restart(); }}
                aria-pressed={isBefore}
                className={`state-chip px-3 py-1.5 text-xs font-semibold transition-all duration-300 border ${isBefore ? 'is-active' : ''}`}>
                {toggleBeforeLabel}
              </button>
              <button onClick={() => { setIsBefore(false); restart(); }}
                aria-pressed={!isBefore}
                className={`state-chip px-3 py-1.5 text-xs font-semibold transition-all duration-300 border ${!isBefore ? 'is-active' : ''}`}>
                {toggleAfterLabel}
              </button>
            </>
          ) : steps.map((label, i) => (
            <button
              key={label}
              onClick={() => { setIndex(i); restart(); }}
              aria-pressed={index === i}
              className={`state-chip px-3 py-1.5 text-xs font-semibold border transition-all duration-300 ${index === i ? 'is-active' : ''}`}
            >
              {label}
            </button>
          ))}
        </div>
      )}
    </div>
  );

  const textEl = (
    <div className={`demo-card-copy flex flex-col gap-4 ${reverse ? 'md:order-1' : ''} md:-mt-[100px]`}>
      {/* Title, visible only on desktop inside text column */}
      <div className="hidden md:block">{titleRow}</div>
      <ul className="demo-points space-y-2">
        {points.map((p, i) => (
          <li key={i} className="flex items-start gap-2 text-slate-300 text-sm">
            <CheckCircle2 className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" />
            <span>{p}</span>
          </li>
        ))}
      </ul>
      <p className="text-slate-300 text-sm leading-relaxed">{description}</p>
    </div>
  );

  return (
    <div id={id} className="demo-card flex flex-col gap-6">
      {/* Title, visible only on mobile, above mockup */}
      <div className="md:hidden">{titleRow}</div>
      {/* Two-column: mockup | text (alternating via CSS order) */}
      <div className="demo-card-grid grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-10 items-center">
        {mockupEl}
        {textEl}
      </div>
    </div>
  );
};

