const lockScroll = (isOpen) => {
  if (isOpen) {
    const sw = window.innerWidth - document.documentElement.clientWidth;
    document.documentElement.style.overflow = 'hidden';
    if (sw > 0) {
      document.documentElement.style.paddingRight = `${sw}px`;
      const h = document.querySelector('header');
      if (h) h.style.paddingRight = `${sw}px`;
    }
  } else {
    document.documentElement.style.overflow = '';
    document.documentElement.style.paddingRight = '';
    const h = document.querySelector('header');
    if (h) h.style.paddingRight = '';
  }
};

const ContactPopup = ({ isOpen, onClose, t }) => {
  useEffect(() => { lockScroll(isOpen); return () => lockScroll(false); }, [isOpen]);
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70" onClick={onClose}>
      <div className="legal-modal backdrop-blur-xl max-w-md w-full p-4" onClick={e => e.stopPropagation()}>
        <div className="legal-modal-header mb-4 p-4 flex items-center justify-between">
          <h3 className="text-xl font-bold text-white">{t('contact.title')}</h3>
          <button onClick={onClose} className="text-white hover:bg-white/20 rounded-full p-2 transition-all duration-200 hover:scale-105"><X size={24} /></button>
        </div>
        <div className="text-center mb-4 mt-8">
          <a href="mailto:contact@qod.ee?subject=ExternalDisplayBrowser%20Support" className="inline-flex items-center gap-2 text-lg font-semibold text-sky-700 dark:text-sky-300 hover:text-sky-800 dark:hover:text-sky-200 transition-colors">
            <Mail size={20} />contact@qod.ee
          </a>
        </div>
        <p className="text-slate-700 dark:text-slate-300 text-center">{t('contact.description')}</p>
      </div>
    </div>
  );
};

