    setHeroMode(mode);
    // Reset the loop timer so it doesn't immediately flip after a manual click
    if (heroLoopRef.current) clearInterval(heroLoopRef.current);
    heroLoopRef.current = setInterval(() => {
      setHeroMode(prev => prev === 'before' ? 'after' : 'before');
    }, 5000);
