// XeLinkShowcase, the two Screen Sharing features side by side: a Mac shown in XeOS (with the
// notarized XeLink for Mac download) and the XeOS desktop shown in any browser (with the browser
// page at /xelink, which walks through connecting). The display (and the laptop made from it) is
// desktopmodeiphone.com's frame (XeosFrames.jsx), and so is the iPhone, in this site's silver. Only what the screens show is new (shared-content/articles/images/xelink-screen-*.svg, the same
// pictures desktopmodeiphone.com uses). Copy: shared-content/locales/<lang>/xelink.json.
import { useTranslation } from 'react-i18next';
import { Download, Globe2, Laptop, MonitorSmartphone } from 'lucide-react';
import { XeosDisplayFrame, XeosLaptopFrame, XeosPhoneFrame } from './XeosFrames';
import macScreen from '../../../shared-content/articles/images/xelink-screen-mac.svg';
import xeosMacScreen from '../../../shared-content/articles/images/xelink-screen-xeos-mac.svg';
import xeosScreen from '../../../shared-content/articles/images/xelink-screen-xeos.svg';
import browserScreen from '../../../shared-content/articles/images/xelink-screen-browser.svg';

const flat = (label) => label.replace(/\n/g, ' · ');
const Screen = ({ src, alt }) => <img src={src} alt={flat(alt)} loading="lazy" decoding="async" />;

/** One long line from device to device, the tip at the end, a pulse running into it. */
const Arrow = ({ label }) => (
  <div className="xelink-arrow" aria-hidden="true">
    <span className="xelink-arrow-label">{label}</span>
    <span className="xelink-arrow-line" /><span className="xelink-arrow-tip" />
  </div>
);

/** A display with the iPhone in front of it, as XeOS really runs. */
const XeosSetup = ({ screen, label, phone = 'left' }) => (
  <div className="xelink-setup">
    <XeosDisplayFrame><Screen src={screen} alt={label} /></XeosDisplayFrame>
    <XeosPhoneFrame className={`xelink-setup-phone ${phone}`}><span className="xelink-phone-screen">XeOS</span></XeosPhoneFrame>
  </div>
);

const Laptop_ = ({ screen, label }) => <XeosLaptopFrame><Screen src={screen} alt={label} /></XeosLaptopFrame>;

const Scene = ({ kind, left, right, arrow, captions }) => (
  <div className={`xelink-row ${kind}`}>
    {left}
    <Arrow label={arrow} />
    {right}
    <p className="xelink-caption">{captions[0]}</p>
    <span />
    <p className="xelink-caption">{captions[1]}</p>
  </div>
);

export default function XeLinkShowcase() {
  const { t } = useTranslation();
  const cards = [
    {
      key: 'mac', icon: Laptop, href: '/downloads/XeLink.dmg', cta: Download, download: true,
      scene: (
        <Scene kind="mac" arrow={t('xelink.devices.arrowMac')}
          left={<Laptop_ screen={macScreen} label={t('xelink.devices.mac')} />}
          right={<XeosSetup screen={xeosMacScreen} label={t('xelink.devices.xeos')} phone="right" />}
          captions={[t('xelink.devices.mac'), t('xelink.devices.xeos')]} />
      ),
    },
    {
      key: 'browser', icon: MonitorSmartphone, href: '/xelink', cta: Globe2,
      scene: (
        <Scene kind="browser" arrow={t('xelink.devices.arrowBrowser')}
          left={<XeosSetup screen={xeosScreen} label={t('xelink.devices.xeos')} />}
          right={<Laptop_ screen={browserScreen} label={t('xelink.devices.browsers')} />}
          captions={[t('xelink.devices.xeos'), t('xelink.devices.browsers')]} />
      ),
    },
  ];
  return (
    <section id="screen-sharing" className="home-xelink py-20 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        <div className="section-intro mb-14">
          <span className="xelink-badge">{t('xelink.badge')}</span>
          <h2 className="text-4xl sm:text-5xl font-bold text-slate-900 dark:text-white">
            <span className="block">{t('xelink.titleLine1')}</span>
            <span className="block">{t('xelink.titleLine2')}</span>
          </h2>
        </div>
        <div className="xelink-grid">
          {cards.map(({ key, icon: Icon, href, cta: Cta, download, scene }) => (
            <article key={key} className="xelink-card">
              <div className="xelink-scene" role="img" aria-label={t(`xelink.${key}.imageAlt`)}>{scene}</div>
              <div className="xelink-copy">
                <h3 className="flex items-center gap-3 text-2xl font-bold text-slate-900 dark:text-white">
                  <span className="feature-icon w-10 h-10 rounded-xl flex items-center justify-center shrink-0"><Icon className="w-5 h-5 text-white" /></span>
                  {t(`xelink.${key}.title`)}
                </h3>
                <p className="text-slate-600 dark:text-slate-300 leading-relaxed">{t(`xelink.${key}.text`)}</p>
                <div className="xelink-actions">
                  <a className="xelink-cta" href={href} {...(download ? { download: 'XeLink.dmg' } : {})}>
                    <Cta className="w-4 h-4" aria-hidden="true" />{t(`xelink.${key}.cta`)}
                  </a>
                  <span className="xelink-note">{t(`xelink.${key}.note`)}</span>
                </div>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}
