// DeviceMockups, the site's device pictures (an iPhone and an iMac, real photos with a
// transparent screen) with whatever the screen shows placed behind the glass. Shared by the
// homepage hero and the Screen Sharing section.
import iphoneMockup120 from '../public/iphone-mockup-120.webp';
import iphoneMockup240 from '../public/iphone-mockup-240.webp';
import iphoneMockup360 from '../public/iphone-mockup-360.webp';
import imac480 from '../public/external-screen-480.webp';
import imac720 from '../public/external-screen-720.webp';
import imac1124 from '../public/external-screen-1124.webp';

export const IPhoneMockup = ({ children, imgClassName = 'w-20', loading = 'lazy', fetchPriority = 'auto', decoding = 'async' }) => (
  <div className="relative inline-block">
    <div className="absolute z-0" style={{top:'2%',left:'3%',width:'94%',height:'96%',overflow:'hidden',borderRadius:'10%'}}>
      {children}
    </div>
    <img
      srcSet={`${iphoneMockup120} 120w, ${iphoneMockup240} 240w, ${iphoneMockup360} 360w`}
      sizes="(min-width: 1024px) 110px, 14vw"
      src={iphoneMockup240}
      alt="iPhone"
      className={`relative z-10 ${imgClassName} h-auto`}
      width={450}
      height={920}
      loading={loading}
      fetchPriority={fetchPriority}
      decoding={decoding}
      style={{filter:'drop-shadow(0 8px 32px rgba(2,132,199,0.28))'}}
    />
  </div>
);

