// XeosFrames, desktopmodeiphone.com's device frames (sites/DesktopModeIphone/src/components/xeos/
// devices.tsx: DisplayFrame, PhoneFrame, LaptopFrame), the same markup and proportions in this
// site's CSS, so the two sites draw a display, a laptop and an iPhone identically. Styles: `.xf-*`
// in design-system.css. Keep both in step if the frames change there.
//
// Every frame is a size container and every part is in cqw of the frame's own width, so a device
// scales as one piece. ONE bezel, the same on all sides, the screen concentric inside it; nothing
// draws outside the frame's box; the display's neck tucks in behind the bezel.

/** A monitor or TV: bezel, 16:9 screen, neck and base, contact shadow. */
export function XeosDisplayFrame({ children, label }) {
  return (
    <span className="xf-display" role={label ? 'img' : undefined} aria-label={label}>
      <span className="xf-bezel"><span className="xf-screen">{children}</span></span>
      <span className="xf-neck" />
      <span className="xf-base" />
      <span className="xf-shadow" />
    </span>
  );
}

/** The display's bezel as a laptop: the same bezel on an open lid (square at the hinge), a 16:10
 *  screen, and under it a deck a little wider than the lid with the opening notch. */
export function XeosLaptopFrame({ children, label }) {
  return (
    <span className="xf-laptop" role={label ? 'img' : undefined} aria-label={label}>
      <span className="xf-lid"><span className="xf-lid-screen">{children}</span></span>
      <span className="xf-deck"><span className="xf-deck-notch" /></span>
    </span>
  );
}

/** An iPhone in portrait: one thin bezel (this site's silver), the screen filling it, the real
 *  corner radius, the Dynamic Island. */
export function XeosPhoneFrame({ children, className = '' }) {
  return (
    <span className={`xf-phone ${className}`.trim()}>
      <span className="xf-phone-bezel"><span className="xf-phone-screen">{children}<span className="xf-island" /></span></span>
    </span>
  );
}
